import csv, hashlib, json, re, subprocess
from collections import defaultdict, deque
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
U = ROOT / 'duanxian/design/upgrades/duanxian-upg-impl-001'
W = ROOT / '.kunora/acc3-work'
BASE = '92573f1cca40f37cee04d2beb8708ff33ba603d6'
CAND = 'b7160de95936198c34434d5b813a02cf4fe7e557'
DEF = '4ce28e8a903adce69579fe08b51bf2b6ff3d842d'
def sha(b): return hashlib.sha256(b).hexdigest()
def git(*args): return subprocess.check_output(['git', *args], cwd=ROOT)
def ptr(obj, p):
    for key in p.strip('/').split('/'):
        key = key.replace('~1','/').replace('~0','~')
        obj = obj[int(key)] if isinstance(obj,list) else obj[key]
    return obj
def bfs(edges, centers):
    adj=defaultdict(set)
    for a,b in edges: adj[a].add(b); adj[b].add(a)
    dist={x:0 for x in centers}; q=deque(centers)
    while q:
        a=q.popleft()
        for b in sorted(adj[a]):
            if b not in dist: dist[b]=dist[a]+1; q.append(b)
    return dist

manifest=json.loads((U/'manifest.json').read_text())
controls=json.loads((U/'01-control-register.json').read_text())['controls']
handoff=json.loads((U/'12-traceability-and-handoff.json').read_text())
source=json.loads((ROOT/'duanxian/conception-approved/human-review-report.json').read_text())
audit={'candidate_commit': CAND,'definition_commit': DEF,'manifest_sha256':sha((U/'manifest.json').read_bytes())}
audit['manifest_files']=[]
for f in manifest['files']:
    b=(U/f['path']).read_bytes()
    audit['manifest_files'].append({**f,'actual_bytes':len(b),'actual_sha256':sha(b),'pass':len(b)==f['bytes'] and sha(b)==f['sha256']})
audit['manifest_file_set_pass']=set(x['path'] for x in manifest['files'])=={x.name for x in U.iterdir() if x.is_file() and x.name!='manifest.json'}
audit['dependencies']=[]
for path,expected in [(manifest['dependency_refs']['definition'].split(' @ ')[0],manifest['dependency_refs']['definition_sha256']), (manifest['dependency_refs']['issue_snapshot'],manifest['dependency_refs']['issue_snapshot_sha256'])]:
    actual=sha((ROOT/path).read_bytes()); audit['dependencies'].append({'path':path,'sha256':actual,'pass':actual==expected})
dp=manifest['dependency_refs']['definition'].split(' @ ')[0]
audit['definition_at_commit_matches']=git('show',DEF+':'+dp)==(ROOT/dp).read_bytes()
audit['controls']=[]
trace={x['control_id']:x for x in handoff['control_trace']['entries']}
for c in controls:
    p=ROOT/c['source_path']; b=p.read_bytes(); loc=c['source_pointer']
    item={'control_id':c['control_id'],'path':c['source_path'],'pointer':loc,'hash_pass':sha(b)==c['source_hash'],'target':trace.get(c['control_id'])}
    if loc.startswith('/'):
        s=ptr(json.loads(b),loc)
        item['projection_checks']={k:c[k]==s[k] for k in ('must_hold','must_not_imply','definition','statement','responsibility') if k in c and k in s}
        item['source_ids_pass']=set(c['source_ids'])==set([s['id']]+s.get('source_ids',[])) if 'id' in s else True
        item['source_value']=s
    else:
        ns=[int(n) for n in re.findall(r'\d+',loc)]; lines=b.decode().splitlines(); selected='\n'.join(lines[ns[0]-1:ns[-1]])
        item['source_value']=selected
        item['projection_checks']={'source_lines_valid':bool(selected)}
    item['consumers_exist']=all((U/x).is_file() for x in c['consumers'])
    audit['controls'].append(item)
audit['control_id_sets_pass']=len(trace)==len(controls)==75 and set(trace)=={c['control_id'] for c in controls}
rows=list(csv.DictReader((U/'03-source-migration.csv').open()))
snap=(ROOT/'.kunora/inputs/open-issues-snapshot-20261114.md').read_text()
audit['migration']=[]
for idx,r in enumerate(rows,1):
    lines=(ROOT/r['old_path']).read_text().splitlines(); n=int(re.search(r'\d+',r['line'])[0]); line=lines[n-1]
    result={'row':idx,'csv_line':idx+1,**r,'actual_source_line':line}
    if idx<=17:
        result['source_exact']=r['old_text']==line
        result['target_exists']=(ROOT/r['target']).is_file()
        result['snapshot_listed']=any(r['old_path'] in x and r['target'] in x for x in snap.splitlines())
        result['prefix_correct']=r['target'].replace('duanxian/design/specs/lld/','docs/superpowers/specs/lld/') in line
    else:
        section=re.search(r'§10\.\d',r['old_text'])[0]
        result['source_section_present']=section in line
    audit['migration'].append(result)
graph=source['visual_models'][4]; rels=source['characters']['relationship_networks'][0]['source_ids']
in_tree=[x for e in graph['edges'] for x in e['source_ids']]
edges=[r.removeprefix('REL-').split('-') for r in in_tree]
# REL identifiers are pair labels; this is a limited reconstruction, not canonical relationships.
normalize={'SHEN':'SHENYU','GU':'GUHENG'}
edges=[tuple(normalize.get(x,x) for x in e) for e in edges]
audit['graph']={'group_distances':bfs([(x['from_node_id'],x['to_node_id']) for x in graph['edges']],['NODE-CHAR-01','NODE-CHAR-02']), 'person_distances_from_18_refs':bfs(edges,['R07','SHENYU']),'total_relations':len(rels),'visible_relations':in_tree,'missing_relations':sorted(set(rels)-set(in_tree)),'boundary':'18条端点由引用ID及可读语义重建；关系本体、方向等未作为已取得canonical声称。5条缺口属于#7。'}
audit['relationship_refs']=[x for x in source['drilldown_index'] if x.get('source_id') in rels]
tracked=git('ls-tree','-rz','--name-only',BASE).decode().split('\0');tracked=[x for x in tracked if x]
audit['base_tree_count']=len(tracked)
audit['skills_count']=len([x for x in tracked if re.fullmatch(r'engine/skills/novel-[^/]+/SKILL.md',x)])
audit['machine_basename_counts']={n:sum(Path(x).name==n for x in git('ls-tree','-rz','--name-only',CAND).decode().split('\0')) for n in ['novel-conception-package.json','development-handoff.json','hld-completion.json']}
audit['existing_base_changes']=git('diff','--name-status',BASE,CAND,'--',*tracked).decode().splitlines()
audit['candidate_revision_changes']=git('diff','--name-only','311b29af7fec928ea987c5e469d2389442cd6348',CAND).decode().splitlines()
audit['attributes']=git('check-attr','--cached','text','eol','--','engine/skills/novel-hld-finalizer/SKILL.md','engine/harnesses/novel-hld-autonomous/manifest.yaml','engine/skills/novel-development-baseline-preparer/SKILL.md').decode().splitlines()
ledger=list(csv.DictReader((U/'07-information-ledger.csv').open()))
audit['ledger_times']=[]
def tick(v):
    m=re.search(r'(?:UPG-)?E-(\d+)(?:\.(\d+))?',v)
    return (int(m[1]),int(m[2] or 0)) if m else None
for idx,row in enumerate(ledger,2):
    ts=[tick(row[k]) for k in ('sent_at','received_at','earliest_use')]
    audit['ledger_times'].append({'id':row['object_id'],'line':idx,'times':ts,'nondecreasing':all(a<=b for a,b in zip(ts,ts[1:]) if a is not None and b is not None),'note':'仅同一行序检查，不证明跨对象来源/能力/接收者语义'})
audit['adaptation_rows']=list(csv.DictReader((U/'10-text-adaptation-map.csv').open()))
audit['secrets']={'scope':'U/全部文件；仅模式扫描，不输出命中内容','matches':[]}
pattern=re.compile(rb'gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|glpat-[A-Za-z0-9_-]{15,}')
for p in U.iterdir():
    if p.is_file() and pattern.search(p.read_bytes()): audit['secrets']['matches'].append(p.name)
(W/'audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n')
print('manifest',audit['manifest_sha256'],'files',len(audit['manifest_files']),'all_match',all(x['pass'] for x in audit['manifest_files']))
print('dependencies',audit['dependencies'],'definition_commit',audit['definition_at_commit_matches'])
print('controls',len(controls),'projection_failures',[(x['control_id'],x['projection_checks']) for x in audit['controls'] if not all(x['projection_checks'].values())], 'ids_failures',[x['control_id'] for x in audit['controls'] if not x.get('source_ids_pass',True)])
print('migration',len(rows),'mechanical_failures',[(x['row'],k) for x in audit['migration'] for k,v in x.items() if isinstance(v,bool) and not v])
print('base_unchanged',not audit['existing_base_changes'],'skills',audit['skills_count'],'machine_counts',audit['machine_basename_counts'])
print('graph',json.dumps(audit['graph'],ensure_ascii=False))
print('ledger',len(ledger),'bad_times',[x for x in audit['ledger_times'] if not x['nondecreasing']],'text_adaptations',len(audit['adaptation_rows']))
print('secrets',audit['secrets'])
